const products=[
 {id:1,name:"Bánh tráng muối",cat:"banhtrang",price:7000,icon:"🍘",image:"data:image/jpeg;base64,",desc:"Bánh tráng đậm vị, cay nhẹ, thơm ngon và ăn là ghiền.",tag:"Bán chạy"},
 {id:2,name:"Nui giòn rim mắm",cat:"nui",price:15000,icon:"🥨",image:"data:image/jpeg;base64,",desc:"Nui giòn vàng ruộm, rim mắm đậm đà, càng ăn càng cuốn.",tag:"Yêu thích"}
];
let cart=JSON.parse(localStorage.getItem("tiemCart")||"[]").filter(i=>i.id===1||i.id===2);
let currentFilter="all";

const money=n=>new Intl.NumberFormat("vi-VN").format(n)+"đ";
function renderProducts(){
 const q=document.getElementById("search").value.toLowerCase().trim();
 const list=products.filter(p=>(currentFilter==="all"||p.cat===currentFilter)&&(!q||p.name.toLowerCase().includes(q)));
 document.getElementById("products").innerHTML=list.length?list.map(p=>`
 <article class="card">
  <div class="product-img">${p.tag?`<span class="tag">${p.tag}</span>`:""}${p.image?`<img src="${p.image}" alt="${p.name}" style="width:100%;height:100%;object-fit:cover;display:block">`:`<div class="placeholder">${p.icon}</div>`}</div>
  <div class="card-body"><h3>${p.name}</h3><p class="desc">${p.desc}</p>
   <div class="card-bottom"><span class="price">${money(p.price)}</span><button class="add" onclick="addToCart(${p.id})">+ Thêm giỏ</button></div>
  </div>
 </article>`).join(""):"<p style='grid-column:1/-1;text-align:center;color:#75695f'>Không tìm thấy món phù hợp.</p>";
}
function save(){localStorage.setItem("tiemCart",JSON.stringify(cart))}
function addToCart(id){
 const p=products.find(x=>x.id===id), found=cart.find(x=>x.id===id);
 if(found)found.qty++;else cart.push({id,qty:1});
 save();renderCart();showToast("Đã thêm "+p.name+" vào giỏ 🛒");
}
function changeQty(id,delta){
 const x=cart.find(i=>i.id===id);if(!x)return;x.qty+=delta;
 if(x.qty<=0)cart=cart.filter(i=>i.id!==id);save();renderCart();
}
function removeItem(id){cart=cart.filter(i=>i.id!==id);save();renderCart()}
function renderCart(){
 const box=document.getElementById("cartItems");
 let total=0,count=0;
 if(!cart.length)box.innerHTML='<div class="empty">🛒<br><br>Giỏ hàng đang trống.<br>Hãy chọn món bạn thích nhé!</div>';
 else box.innerHTML=cart.map(i=>{const p=products.find(x=>x.id===i.id);total+=p.price*i.qty;count+=i.qty;return `
 <div class="cart-item"><div class="thumb">${p.icon}</div><div><h4>${p.name}</h4><small>${money(p.price)}</small><div class="qty"><button onclick="changeQty(${p.id},-1)">−</button><span>${i.qty}</span><button onclick="changeQty(${p.id},1)">+</button></div></div>
 <div class="cart-price">${money(p.price*i.qty)}<br><button class="remove" onclick="removeItem(${p.id})">Xóa</button></div></div>`}).join("");
 document.getElementById("cartCount").textContent=count;
 document.getElementById("cartTotal").textContent=money(total);
}
function openCart(){document.getElementById("drawer").classList.add("open");document.getElementById("overlay").classList.add("show");document.body.classList.add("cart-open")}
function closeCart(){document.getElementById("drawer").classList.remove("open");document.getElementById("overlay").classList.remove("show");document.body.classList.remove("cart-open")}
function showToast(text){const t=document.getElementById("toast");t.textContent=text;t.classList.add("show");clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.classList.remove("show"),2200)}
function readMore(title){showToast("Bài viết: "+title)}
document.querySelectorAll(".filter").forEach(b=>b.addEventListener("click",()=>{document.querySelectorAll(".filter").forEach(x=>x.classList.remove("active"));b.classList.add("active");currentFilter=b.dataset.filter;renderProducts()}));
document.getElementById("search").addEventListener("input",renderProducts);

const select=document.getElementById("productSelect");
products.forEach(p=>{const o=document.createElement("option");o.value=p.id;o.textContent=p.name+" - "+money(p.price);select.appendChild(o)});
document.getElementById("orderForm").addEventListener("submit",e=>{
 e.preventDefault();
 const selected=select.value;
 if(selected)addToCart(Number(selected));
 document.getElementById("success").classList.add("show");
 e.target.reset();
 document.getElementById("quantity").value=1;
 document.getElementById("success").scrollIntoView({behavior:"smooth",block:"center"});
 showToast("Đơn hàng đã được ghi nhận 🎉");
});
renderProducts();renderCart();
